def load_native_bdd(source: str, *, profile: str, recorder=None) -> BDDResult:
    digest = sha256(source.encode("utf-8")).hexdigest()
    try:
        facts = context(load_yaml_text(source), profile)
    except (DuplicateKeyError, yaml.YAMLError, ValueError, TypeError) as error:
        code = "duplicate_yaml_key" if isinstance(error, DuplicateKeyError) else "invalid_value"
        if recorder is not None:
            for policy in POLICIES:
                recorder.skipped(policy.rule_ref)
        return BDDResult(
            profile,
            BDDScenarioPresence.INVALID,
            (issue(code, "document"),),
            tuple(PolicyOutcome(p.rule_ref, "skipped", "invalid_yaml_boundary") for p in POLICIES),
            (),
            digest,
            POLICIES[0].safe_trace_label(profile),
        )
    return evaluate(facts, digest, recorder=recorder)

def lint_file(path: Path) -> list[LintIssue]:
    issues: list[LintIssue] = []
    try:
        source = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return [LintIssue(path=path, message="file does not exist")]

    try:
        data = load_yaml_text(source)
    except Exception as exc:
        return [LintIssue(path=path, message=str(exc))]

    for message in _validate_spec_shape(data):
        issues.append(LintIssue(path=path, message=message))

    canonical = dump_canonical_yaml(data)
    if source != canonical:
        issues.append(
            LintIssue(
                path=path,
                message=(
                    "file is not canonically formatted; run "
                    f"`python tools/spec_yaml_format.py {path}`"
                ),
            )
        )
    return issues
